import{_ as r,l,o as e,c as P,v as t,p,x as i,d as n,i as s,S as d}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"CPP 与 MMP","description":"","frontmatter":{"title":"CPP 与 MMP","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/cpp-mmp.md","filePath":"litho/cpp-mmp.md","lastUpdated":1789023840000}'),m={name:"litho/cpp-mmp.md"};function c(h,a,M,E,_,C){const o=l("Mermaid");return e(),P("div",null,[a[1]||(a[1]=t('<h1 id="cpp-与-mmp" tabindex="-1">CPP 与 MMP <a class="header-anchor" href="#cpp-与-mmp" aria-label="Permalink to &quot;CPP 与 MMP&quot;">​</a></h1><div class="epigraph"><p>接触多晶节距卡住栅方向密度；最小金属节距卡住互连。两根尺子分开缩，光刻层的分解策略也可以分开选。</p><footer>—— 对照 contacted poly pitch 与 minimum metal pitch 作为 DTCO 度量的通称</footer></div><p><a href="/litho/node-naming">上一课</a>丢掉商品名当尺子。缺口是代用尺子。本课钉 CPP 与 MMP。如何合成晶体管密度，留给[下一课](/litho/transistor-density-metric）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CPP（contacted poly pitch）：相邻栅（含接触落地）的周期，约束鳍/片上的逻辑密度。MMP（minimum metal pitch）：最密金属周期，约束布线与 via 网格。前端 EUV/多重与后道 EUV/多重可以不同步——BEOL 课已见混波长。轨道高度 = 轨数 ×（某层金属节距），与 CPP 正交。</p><p>缺口是<strong>两根独立节距</strong>，不是一个「节点 nm」。把 CPP 当成所有层的节距，会误判金属是否该上 EUV。</p><h3 id="与单次极限的关系" tabindex="-1">与单次极限的关系 <a class="header-anchor" href="#与单次极限的关系" aria-label="Permalink to &quot;与单次极限的关系&quot;">​</a></h3><p>浸没单次半节距约 38–40 nm 量级（Mack/ASML 公开叙事，主干已用）。MMP 低于约两倍半节距就要分解或换波长。本课不重推，只把尺子对上那条墙。</p><p><span class="marginnote">公开 CPP/MMP 数字随演讲年份变。课文用定义，不把某年 ISSCC 一页当永远真值。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>DTCO：分别扫 CPP、MMP 的可印路径（SAQP、LELE、EUV 单/双）。成本按层加总。SRAM 往往两边都最紧。报告节点进展时同时报两数与轨道高度。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>逻辑晶体管占地 ≈ CPP × 单元高度；高度又是 MMP 与轨数的函数。所以密度对两尺都敏感。光刻机台选择按层跟尺走：栅切线跟 CPP，M0/M1 跟 MMP。</p>',13)),(e(),p(d,null,{default:i(()=>[s(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20CPP%5B%22CPP%22%5D%20--%3E%20FEOL%5B%22%E6%A0%85%20%2F%20%E5%88%87%E7%BA%BF%20%2F%20%E6%8E%A5%E8%A7%A6%22%5D%0A%20%20MMP%5B%22MMP%22%5D%20--%3E%20BEOL%5B%22%E5%AF%86%E9%87%91%E5%B1%9E%20%2F%20via%22%5D%0A%20%20CPP%20--%3E%20DENS%5B%22%E5%AF%86%E5%BA%A6%22%5D%0A%20%20HT%5B%22%E8%BD%A8%20%C3%97%20%E9%87%91%E5%B1%9E%E8%8A%82%E8%B7%9D%22%5D%20--%3E%20DENS%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>尺子不包含 3D 堆叠的垂直密度（后课 3D NAND）。不把 CPP 当 Fin 节距——鳍节距是第三尺，有时单独报。</p><p>后课默认：平面密度用 CPP×高度；下一课把多种密度口径（MTr/mm²、NAND2、SRAM）拆开。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CPP 与 MMP 是正交的可缩尺子，层策略可不同步。</li><li>单元高度把 MMP 接到密度公式。</li><li>对单次极限时用这些尺，不用商品名。</li><li>出处：代工/imec 对 CPP、MMP 的 DTCO 通称。</li></ul>',5))])}const f=r(m,[["render",c]]);export{u as __pageData,f as default};
